    # map each archetype to its rounded average atk
    pass

exercises.solution:
def avg_atk_by_archetype(cards):
    sums, counts = {}, {}
    for c in cards:
        sums[c['archetype']] = sums.get(c['archetype'], 0) + c['atk']
        counts[c['archetype']] = counts.get(c['archetype'], 0) + 1
    return {a: round(sums[a] / counts[a]) for a in sums}

exercises.starter:
def archetype_with_most_cards(cards):
    # return the archetype with the most cards
    pass

exercises.solution:
def archetype_with_most_cards(cards):
    counts = {}
    for c in cards:
        counts[c['archetype']] = counts.get(c['archetype'], 0) + 1
    best, best_count = None, 0
    for a in sorted(counts):
        if counts[a] > best_count:
            best_count, best = counts[a], a
    return best

exercises.starter:
def strongest_per_archetype(cards):
    # map each archetype to the name of its highest-atk card
    pass

exercises.solution:
def strongest_per_archetype(cards):
    best = {}
    for c in cards:
        if c['archetype'] not in best or c['atk'] > best[c['archetype']]['atk']:
            best[c['archetype']] = c
    return {a: c['name'] for a, c in best.items()}

